"use client";import{useEffect,useState}from"react";import PageTitle from"@/composants/ui/PageTitle";import Section from"@/composants/ui/Section";import{apiRequest}from"@/services/api.js";
const labels={emis:"Émis",paye:"Payé"};export default function Page(){const[items,setItems]=useState([]),[error,setError]=useState("");useEffect(()=>{apiRequest('/api/v1/finance/payouts').then(r=>setItems(r.data||[])).catch(e=>setError(e.message))},[]);return <div className="space-y-8"><PageTitle title="Mes bons de paiement" description="Consultez les montants dus pour les colis réellement retirés."/>{error&&<p className="text-sm text-red-700">{error}</p>}<Section title={`${items.length} bon(s)`}>{items.length===0?<p className="text-sm text-slate-600">Aucun bon de paiement disponible.</p>:<div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className="border-b text-left"><th className="p-3">Période</th><th className="p-3">Colis retirés</th><th className="p-3">Tarif</th><th className="p-3">Montant</th><th className="p-3">État</th></tr></thead><tbody>{items.map(i=><tr key={i.id} className="border-b border-slate-100"><td className="p-3 font-bold">{i.period}</td><td className="p-3">{i.parcels}</td><td className="p-3">{Number(i.unit).toFixed(2)} €</td><td className="p-3 font-bold">{Number(i.amount).toFixed(2)} €</td><td className="p-3">{labels[i.status]||i.status}</td></tr>)}</tbody></table></div>}</Section></div>}
